The school falls under the Western Cape Education Department''s Metro North district, placing it within the province''s standard public schooling structure alongside the area''s other government and faith-based primary schools. Based in Matroosfontein, on Cape Town''s northern suburbs rail corridor, it serves families in the surrounding community looking for a public primary school option close to home.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.westerncape.gov.za/education/facility/matroosberg-holy-trinity-rc-primary-school', '$[#]', 'https://www.callupcontact.com/b/Public_Primary_Elementary_Schools/MATROOS_HOLY_TRINITY_RC_PRIMARY_SCHOOL/7388'), description_enriched_at = datetime('now') WHERE slug = 'holy-trinity-rc-primary-school-matroosfontein' AND description = 'Holy Trinity RC Primary School is a public Roman Catholic primary school on St Dominic Street, Matroosfontein, with around 786 learners and 25 teachers, part of the Western Cape Education Department''s Metro North district.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
